package com.sap.bfx.callback;import java.io.InputStream;/** * */public interface AttachmentAdapter extends Adapter {    /**     * @param id     * @param is     * @param fileName     * @param contentType     * @param size     * @param category     * @param description     * @return     */    String save(final String id, final InputStream is, final String fileName, final String contentType,                final long size, final String category, final String description);    /**     * @param ref     * @return     */    InputStream load(final String ref);    /**     * @param ref     */    void delete(final String ref);}